  def achievement_icon_svg(icon_key, css_class: "w-6 h-6", stroke_width: "1.5", color_class: "text-green-400")
    path = ICON_PATHS[icon_key.to_sym] || ICON_PATHS[:star]
    tag.svg(class: "#{css_class} #{color_class}", fill: "none", viewBox: "0 0 24 24",
            stroke: "currentColor", "stroke-width": stroke_width) do
      raw(path)
    end
  end
